/** Exercise the visible provider control; the hidden select is only a form adapter. */
export async function chooseProvider(page, providerId) {
  await page.locator("#cfg-provider-trigger").click();
  await page.locator("#cfg-provider-search").fill(providerId);
  await page.locator(`#cfg-provider-list [data-provider-id="${providerId}"]`).click();
}

import { expect, test } from "./fixtures.mjs";

test("native history sweep preserves shared references and deletes the last one", async ({ page }) => {
  await page.goto("/__test_health");
  const result = await page.evaluate(async () => {
    const { createMemoryStorage } = await import("/tests/support/memory-storage.mjs");
    const { createSessionRepository } = await import("/extension/background/session/repository.js");
    const { createSessionRecord } = await import("/extension/shared/session/session-codec.js");
    const { getHistoryImage } = await import("/extension/shared/asset-store.js");
    const storage = createMemoryStorage();
    const repository = createSessionRepository({ storage });
    const image = "data:image/png;base64,AAAA";
    const record = createSessionRecord([{ role: "user", content: [{ type: "image_url", image_url: { url: image } }] }], []);
    await repository.writeRecord("one", record);
    await repository.writeRecord("two", record);
    const reference = storage.snapshot()._session_one.conversation.entries[0].message.content[0].image_url.url;
    await repository.deleteSession("one");
    const shared = await getHistoryImage(reference);
    await repository.deleteSession("two");
    const removed = await getHistoryImage(reference);
    return { image, shared, removed };
  });
  expect(result.shared).toBe(result.image);
  expect(result.removed).toBeNull();
});

test("native asset DB upgrade, GC and reload preserve inline history and offline export", async ({ page, context }) => {
  await page.goto("/__test_health");
  const stored = await page.evaluate(async () => {
    // Upgrade an existing gallery DB without replacing its assets.
    await new Promise((resolve, reject) => {
      const request = indexedDB.open("qz-browser-agent-assets", 1);
      request.onupgradeneeded = () => {
        const store = request.result.createObjectStore("image_assets", { keyPath: "assetId" });
        for (const key of ["sha256", "updatedAt", "lastAccessedAt"]) store.createIndex(key, key, { unique: key === "sha256" });
      };
      request.onsuccess = () => { request.result.close(); resolve(); };
      request.onerror = () => reject(request.error);
    });
    const canvas = document.createElement("canvas");
    canvas.width = canvas.height = 2;
    canvas.getContext("2d").fillRect(0, 0, 2, 2);
    const image = canvas.toDataURL("image/png");
    const { saveHistoryImage, gcImageAssets } = await import("/extension/shared/asset-store.js");
    const { persistSessionImages } = await import("/extension/shared/session/session-image-assets.js");
    const { createSessionRecord } = await import("/extension/shared/session/session-codec.js");
    const refs = await Promise.all(Array.from({ length: 6 }, () => saveHistoryImage(image)));
    const record = createSessionRecord([{ role: "user", content: [{ type: "image_url", image_url: { url: image } }] }], [
      { type: "user", text: "upload", images: [{ dataUrl: image }] },
      { type: "tool", name: "screenshot", image, args: {}, result: { ok: true } },
    ]);
    const snapshot = await persistSessionImages(record);
    await gcImageAssets({ maxImages: 0, maxBytes: 0, dryRun: false });
    localStorage.setItem("snapshot", JSON.stringify(snapshot));
    localStorage.setItem("image", image);
    const count = await new Promise((resolve, reject) => {
      const request = indexedDB.open("qz-browser-agent-assets", 2);
      request.onsuccess = () => {
        const db = request.result;
        const tx = db.transaction("history_images");
        const count = tx.objectStore("history_images").count();
        tx.oncomplete = () => { db.close(); resolve(count.result); };
        tx.onerror = () => reject(tx.error);
      };
    });
    return { refs, count, json: JSON.stringify(snapshot) };
  });
  expect(new Set(stored.refs).size).toBe(1);
  expect(stored.count).toBe(1);
  expect(stored.json).not.toContain("data:image/");
  await page.reload();
  const restored = await page.evaluate(async () => {
    const { resolveSessionImages } = await import("/extension/shared/session/session-image-assets.js");
    const { readSessionRecord, deserializeConversation } = await import("/extension/shared/session/session-codec.js");
    const { createSessionExchangePayload } = await import("/extension/shared/session/session-exchange.js");
    const { buildSessionExportHtml } = await import("/extension/sidepanel/features/export/session-export-feature.js");
    const image = localStorage.getItem("image");
    const saved = readSessionRecord(await resolveSessionImages(JSON.parse(localStorage.getItem("snapshot"))));
    const session = { id: "native-images", title: "Images" };
    const payload = createSessionExchangePayload({ session, ...saved });
    const container = document.createElement("div");
    for (const entry of saved.transcript) {
      const img = document.createElement("img");
      img.src = entry.image || entry.images[0].dataUrl;
      container.append(img);
      await img.decode();
    }
    document.body.append(container);
    return { image, replay: deserializeConversation(saved.conversation)[0].content[0].image_url.url,
      html: buildSessionExportHtml(session, payload, { chatHtml: container.innerHTML }) };
  });
  expect(restored.replay).toBe(restored.image);
  expect(restored.html).not.toContain("qz-history-image:");
  await expect(page.locator("img")).toHaveCount(2);
  const offline = await context.newPage();
  await context.setOffline(true);
  await offline.setContent(restored.html);
  const images = await offline.locator("img").evaluateAll(async images => {
    await Promise.all(images.map(image => image.decode()));
    return images.map(image => ({ src: image.getAttribute("src"), width: image.naturalWidth }));
  });
  expect(images).toEqual([{ src: restored.image, width: 2 }, { src: restored.image, width: 2 }]);
  await offline.close();
});

import { expect, test } from './sidepanel-fixtures.mjs';
import { chooseProvider } from './provider-picker-fixture.mjs';

const provider = {
  id: 'fixture-device', label: 'Fixture device', requiresApiKey: false, auth: { label: 'Fixture' },
  modelOptions: [{ key: 'fixtureQuality', label: 'Quality', defaultValue: 'balanced', options: [
    { value: 'balanced', label: 'Balanced' }, { value: 'precise', label: 'Precise' },
  ] }],
};

async function configure(page) {
  await page.locator('#btn-settings').click();
  await page.evaluate(provider => {
    window.__loginWindows = [];
    window.open = url => { window.__loginWindows.push(url); return null; };
    window.__qzEmitPortMessage({ type: 'config', config: {
      provider: provider.id, providers: [provider, { id: 'deepseek', label: 'DeepSeek', requiresApiKey: true }], providerAuth: { [provider.id]: { loggedIn: false } },
      model: 'fixture-local', contextWindow: 64000, presets: [], providerApiKeys: {},
      securityGuardrails: { rules: [], siteOpenRateLimits: [], order: [] },
    } });
  }, provider);
  await expect(page.locator('#btn-provider-login')).toHaveText('Fixture 登录');
}

async function latestRequest(page, type) {
  await expect.poll(() => page.evaluate(type => window.__qzPostedMessages.filter(message => message.type === type).length, type)).toBeGreaterThan(0);
  return page.evaluate(type => window.__qzPostedMessages.filter(message => message.type === type).at(-1), type);
}
const login = { loginId: 'fixture-login', userCode: 'LOCAL-CODE', verificationUri: 'https://example.invalid/login', intervalSeconds: 1, expiresAt: Date.now() + 3600000 };

async function reply(page, request, type, fields) {
  await page.evaluate(({ request, type, fields }) => window.__qzEmitPortMessage({ type, requestId: request.requestId, ...fields }), { request, type, fields });
}

test('an arbitrary provider renders declared login and model options and retains a login failure', async ({ page }) => {
  await configure(page);
  await expect(page.locator('#cfg-apikey-field')).toBeHidden();
  await expect(page.locator('#cfg-provider-option-fixtureQuality')).toHaveValue('balanced');
  await page.locator('#cfg-provider-option-fixtureQuality').selectOption('precise');
  await page.locator('#btn-provider-login').click();
  const request = await latestRequest(page, 'start_provider_login');
  expect(request.provider).toBe(provider.id);
  await reply(page, request, 'error', { code: 'AUTH_UNAVAILABLE', message: 'Fixture login unavailable' });
  await expect(page.locator('#provider-auth-status')).toHaveText('Fixture login unavailable');
  await expect(page.locator('#btn-provider-login')).toBeEnabled();
  await expect(page.locator('#cfg-provider-option-fixtureQuality')).toHaveValue('precise');
});

test('switching providers discards a late login start without opening a page or resuming polling', async ({ page }) => {
  await configure(page);
  await page.locator('#btn-provider-login').click();
  const request = await latestRequest(page, 'start_provider_login');
  await chooseProvider(page, 'deepseek');
  await reply(page, request, 'provider_login_started', login);
  await chooseProvider(page, provider.id);
  await expect(page.locator('#btn-provider-login')).toBeEnabled();
  await expect(page.locator('#provider-device-box')).toBeHidden();
  expect(await page.evaluate(() => window.__loginWindows)).toEqual([]);
  expect(await page.evaluate(() => window.__qzPostedMessages.filter(message => message.type === 'poll_provider_login'))).toEqual([]);
});

test('closing a draft discards an in-flight login poll and clears its next timer', async ({ page }) => {
  await configure(page);
  await page.clock.install();
  await page.locator('#btn-provider-login').click();
  await reply(page, await latestRequest(page, 'start_provider_login'), 'provider_login_started', login);
  await expect(page.locator('#provider-device-code')).toHaveText('LOCAL-CODE');
  await page.clock.runFor(1200);
  const poll = await latestRequest(page, 'poll_provider_login');
  expect(poll.provider).toBe(provider.id);
  expect(poll.loginId).toBe(login.loginId);
  await page.locator('#btn-close-settings').click();
  await reply(page, poll, 'provider_login_polled', { status: 'pending', intervalSeconds: 1 });
  await page.clock.runFor(5000);
  expect(await page.evaluate(() => window.__qzPostedMessages.filter(message => message.type === 'poll_provider_login').length)).toBe(1);
});

import { createTestAgentServices } from './agent-services.mjs';
import { attachProviderRecovery, providerRecoveryHint } from '../../src/background/llm/provider-recovery.js';
import { normalizeLlmFailure } from '../../src/background/llm/provider-errors.js';
import { trace } from '../../src/background/trace.js';

globalThis.chrome = {
  debugger: {
    onDetach: { addListener() {} },
    onEvent: { addListener() {} },
  },
  runtime: { getURL: path => path },
  storage: { local: { async get() { return {}; }, async set() {}, async remove() {} } },
};

const { Agent } = await import("../../src/background/agent/agent.js?provider-error-recovery");

export function createAgent(llm, { provider = "", retry = null } = {}) {
  const agent = new Agent("provider-recovery-session", {
    conversationRepository: {
      readActiveConversation: async () => null,
      writeActiveConversation: async () => true,
      clearActiveConversation: async () => true,
    },
    conversationLease: { sessionId: "provider-recovery-session", isActive: () => true },
    services: createTestAgentServices({ trace, getRuntimeConfig: async () => ({ provider, model: "test", contextWindow: 262000 }) }),
    llm: {
      ...llm,
      async *chatStream(...args) {
        try { yield* llm.chatStream(...args); }
        catch (error) { const failure = normalizeLlmFailure(error); throw attachProviderRecovery(failure, providerRecoveryHint(failure, { provider })); }
      },
    },
    tools: { execute: async () => ({}), getIdentity: () => ({}), getSchemas: () => [] },
    browserContext: { readSelectedText: async () => "", getTab: async () => null },
    sessionPolicy: { canManageSessions: async () => true },
  });
  agent._currentRunId = "provider-recovery-run";
  if (retry) {
    const getLlmOptions = agent._llmOptions.bind(agent);
    agent._llmOptions = () => ({ ...getLlmOptions(), retry });
  }
  agent._persistIfToolLedgerRepaired = async () => false;
  agent._ensureDynamicContextSnapshot = async () => ({});
  agent._appendGoalSnapshotIfDue = async () => false;
  agent._prepareSendWindowOrBlock = async () => ({
    ok: true,
    status: "ok",
    sendBoundaryId: "boundary-test",
    sendMessages: [],
    contextEstimate: { tokens: 0, messageCount: 0 },
  });
  agent._emitSendWindowContextUsage = () => {};
  agent._traceSendWindow = () => {};
  agent._stampAssistantUsageContext = () => {};
  agent._emitProviderContextUsage = () => {};
  return agent;
}

export function createLoopAgent(responses) {
  const agent = createAgent({ chat: async () => ({}), chatStream: async function* () {} });
  const queue = [...responses];
  agent.messages = [
    { role: "system", content: "system" },
    { role: "user", content: "需要澄清后继续" },
  ];
  agent._callLLM = async () => queue.shift();
  agent._persistConversation = async () => true;
  agent._flushPendingContextEvents = async () => {};
  return agent;
}

import { createTestAgentServices } from "../support/agent-services.mjs";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { createAgentBrowserContext } from "../../src/background/session/browser-context.js";

delete globalThis.chrome;

const { Agent } = await import("../../src/background/agent/agent.js?runtime-dependencies");

const calls = [];
const browserContext = createAgentBrowserContext({
  scripting: {
    executeScript: async options => {
      calls.push(["selection", options.target.tabId]);
      return [{ result: "selected text" }];
    },
  },
  tabs: {
    get: async tabId => {
      calls.push(["tab", tabId]);
      if (tabId === 10) {
        return {
          id: tabId,
          title: "about:blank",
          url: "about:blank",
          pendingUrl: "https://example.test/loading",
        };
      }
      return { id: tabId, title: "Page", url: "https://example.test/page" };
    },
  },
});

assert.equal(await browserContext.readSelectedText(9), "selected text");
assert.deepEqual(await browserContext.getTab(9), { id: 9, title: "Page", url: "https://example.test/page" });
assert.equal(await browserContext.readSelectedText(0), "");
assert.equal(await browserContext.getTab("bad"), null);

const stalledSelectionContext = createAgentBrowserContext({
  scripting: { executeScript: () => new Promise(() => {}) },
  selectionReadTimeoutMs: 10,
});
const stalledSelectionStartedAt = Date.now();
assert.equal(await stalledSelectionContext.readSelectedText(9), "");
assert.ok(Date.now() - stalledSelectionStartedAt < 500, "stalled page injection must fail open promptly");

const agent = new Agent("session-child", {
    services: createTestAgentServices(),
  conversationRepository: {
    readActiveConversation: async () => null,
    writeActiveConversation: async () => true,
    clearActiveConversation: async () => true,
  },
  conversationLease: { sessionId: "session-child", isActive: () => true },
  llm: { chat: async () => ({}), chatStream: async function* () {} },
  tools: { execute: async () => ({}), getIdentity: () => ({}), getSchemas: () => [], getModelPolicy: () => ({ pageContext: "working" }) },
  browserContext,
  sessionPolicy: { canManageSessions: async sessionId => sessionId !== "session-child" },
});

assert.equal(await agent._canManageSessions(), false);
agent.setDynamicContextProvider(async () => ({ userVisibleTab: { id: 9 } }));
assert.equal((await agent._collectDynamicContext()).selectionText, "selected text");
const explicitCalls = [];
agent._toolRuntime.execute = async (_name, args) => { explicitCalls.push(args); return { text: 'page' }; };
agent._dynamicContextSnapshot = { workingTab: { id: 10 }, userVisibleTab: { id: 9 } };
await agent._executeToolCalls([{ id: 'explicit', function: { name: 'read_dom', arguments: '{"tabRef":9}' } },
  { id: 'missing', function: { name: 'read_dom', arguments: '{}' } }], new AbortController().signal);
assert.deepEqual(explicitCalls, [{ tabRef: 9 }, {}], 'Agent forwards caller targets without a context-derived default');
assert.ok(calls.some(call => call[0] === "selection" && call[1] === 9));
assert.ok(calls.some(call => call[0] === "tab" && call[1] === 9));

const document = {
  sessionId: "session-child",
  messageId: "message-1",
  attachmentId: "attachment-1",
  fileId: "file-1",
  docModelId: "model-1",
  filename: "example.py",
  mimeType: "text/x-python",
  format: "code",
  size: 42,
};
