import { normalizeImage } from './shared/images/normalize.js';
import type { ImageNormalizeOptions } from './shared/images/normalize.js';
import { parseImageDataUrlHeader } from './shared/images/policy.js';
import { decodeImageInDom } from './dom/image-decoder.js';

// Loading SVG as an image disables scripts and external subresources.
export async function normalizeSvgImage(dataUrl: unknown, options: Omit<ImageNormalizeOptions, 'decode' | 'signal'> = {}) {
  if (typeof dataUrl !== 'string' || parseImageDataUrlHeader(dataUrl).mimeType !== 'image/svg+xml') throw new Error('Invalid SVG image input');
  return normalizeImage(dataUrl, { ...options, format: options.format || 'png', decode: decodeImageInDom });
}

import { assertImageDimensions, ImageLimitError } from '../shared/images/policy.js';
import { imageT } from '../shared/images/messages.js';

/** SVG uses the image-only DOM decoder, which disables scripts and subresources. */
export async function decodeImageInDom(blob: Blob): Promise<ImageBitmap> {
  if (blob.type !== 'image/svg+xml') return createImageBitmap(blob);
  const url = URL.createObjectURL(blob);
  const image = new Image();
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    await new Promise<void>((resolve, reject) => {
      image.onload = () => resolve();
      image.onerror = () => reject(new ImageLimitError('IMAGE_DECODE_FAILED', imageT('decode')));
      timer = setTimeout(() => reject(new ImageLimitError('IMAGE_DECODE_FAILED', imageT('decode'))), 10000);
      image.src = url;
    });
    assertImageDimensions(image.naturalWidth, image.naturalHeight);
    return await createImageBitmap(image);
  } finally { clearTimeout(timer); image.src = ''; URL.revokeObjectURL(url); }
}

